DELETE FROM MSECGRPFUN WHERE FACTORY = 'SYSTEM' AND PROGRAM_ID = 'MESClient' AND SEC_GRP_ID = 'ADMIN_GROUP';


/* Add YESNO GCM Table */




BEGIN
	 FOR REC IN (
				SELECT FACTORY FROM MWIPFACDEF
				MINUS
				SELECT FACTORY FROM MGCMTBLDEF 
				WHERE TABLE_NAME = 'YESNO'
				) 
	  LOOP


	  END LOOP;			
END ;
/


